/// The QR code for `payload` as a texture: black modules on white with
/// the quiet zone, scaled so a phone reads it from the screen.
fn qr_texture(ctx: &Context, payload: &str) -> Option<egui::TextureHandle> {
    let code = qrcode::QrCode::new(payload.as_bytes()).ok()?;
    let width = code.width();
    let modules = code.to_colors();
    let side = (width + 2 * QR_QUIET) * QR_SCALE;
    let mut pixels = vec![egui::Color32::WHITE; side * side];
    for (i, module) in modules.iter().enumerate() {
        if *module != qrcode::Color::Dark {
            continue;
        }
        let (x, y) = (i % width + QR_QUIET, i / width + QR_QUIET);
        for dy in 0..QR_SCALE {
            for dx in 0..QR_SCALE {
                pixels[(y * QR_SCALE + dy) * side + x * QR_SCALE + dx] = egui::Color32::BLACK;
            }
        }
    }
    let image = egui::ColorImage::new([side, side], pixels);
    Some(ctx.load_texture("remote-pairing-qr", image, egui::TextureOptions::NEAREST))
}

/// The first sixteen hex digits of a key hash in groups of four: what
/// a person compares against the client's screen.
fn short_hash(hex: &str) -> String {
    hex.chars()
        .take(16)
        .collect::<Vec<_>>()
        .chunks(4)
        .map(|c| c.iter().collect::<String>())
        .collect::<Vec<_>>()
        .join(" ")
}

/// "ABCD EFGH": the code in two halves, as it is read aloud.
fn spaced(code: &str) -> String {
    let (a, b) = code.split_at(code.len() / 2);
    format!("{a} {b}")
}
# Spike 22: the remote port over std

The questions from `docs/remote-client.md` §10 that the host side can
answer without a client: can a pinned-TLS HTTP and WebSocket port run on
std threads with every request answered by the frame thread, what the
handoff costs, whether the bounds of §4.1 hold under abuse, whether
Bonjour works from Rust, what a transcript costs to parse, and whether
the content-version signals of §4.4 see the changes that defeat weaker
ones. The visionOS half (a `URLSession` pinning delegate accepting the
certificate and refusing a substitute) is not here: it needs an Xcode
project and the simulator.

Standalone crate, not built by the app. Builds into the repo's shared
`target/` like every crate under this tree.

